/* The Myconica – deutscher Buchtext (Storm and Root S. 258–269). Index 0 der Wache-Listen = Ergebnis 6. */
window.WS_REICH = window.WS_REICH || {};
WS_REICH.myconica = {
 t:"The Myconica", p:258, q:"sr",
 kurz:"Ein Reich – wenn man es denn so nennen kann – aus einem einzigen, alles verzehrenden Pilzgeflecht, in dem Geheimnisse über den Ursprung der Gau schlummern sollen.",
 intro:"Diese Seite hebt die wichtigsten Elemente der Myconica hervor, eines Reichs … wenn man es denn so nennen kann … das aus einem einzigen, alles verzehrenden Pilzgeflecht besteht, in dem Geheimnisse über den Ursprung der Gau vermutet werden. Der Rest dieses Abschnitts geht mehr ins Detail.",
 elemente:[
  {t:"Dimm", x:"Der Name der ausufernden Pilzmasse, die den Großteil der örtlichen Wellenkämme bildet: „Dimm“ hat sich durch jede Eisenwurzel des Reichs ausgebreitet. Ob der Organismus gleichgültig, wohlwollend oder schlicht ohne Verstand ist, fragen die Einheimischen selten – sie glauben, was ihnen am meisten zusagt, welche Wahrheit ihr Dasein in einem solchen Reich erträglicher macht.",
   erleben:["Die knochenweißen Überreste einer alten Eisenwurzel, besetzt mit Pilzkonsolen","Ein Stadthafen, gebaut unter einer Pilzkappe, was versponnen wirken würde, wären da nicht die erstickenden Sporenwolken in der Luft und das ständige Schnappen und Knurren von Sporenhunden aus schattigen Straßenecken","Rollende „Wellen“, die sich ohne Brise oder vorbeifahrende Schiffe bewegen, Wedel und Fäden feucht glänzend"]},
  {t:"Sägen für die Astlosen", x:"Schiffe, die für die typischen Blatt- und Astwellen der Wildsee gebaut sind, können die zitternde Pilzmasse der Myconica durchaus befahren, doch das bringt eine Reihe von Problemen mit sich. Besonders betroffen sind Schiffe, die sich auf Sägen verlassen, einen Grundpfeiler der weiteren Wellen – die Sägezähne zerreißen Sporenklumpen und Reizmassen und füllen die Luft mit infektiösen Wolken.",
   erleben:["Ein Sägebug oder Langkiefer, im Wuchs eingeklemmt, der Motor still, das Deck von eitrigen Auswüchsen übersät, die einst die Crew gewesen sein könnten","Gau-Mycosanctums, die fröhlich von Ort zu Ort rollen","Einheimische Schiffe, die auf Tausendfüßler-Gliedmaßen, Tentakelanbauten und schräge Raupenketten setzen"]},
  {t:"Die Luft selbst ein Schlot", x:"Über der Myconica gibt es keine Stürme am Himmel, und doch ist er leer von Luftschiffen. Aufsteigende Sporen ballen sich zu treibenden Wolken, die Motoren verstopfen und Bernsteinglas undurchsichtig machen. Ganze Arten saprophytischer Kreaturen sollen in diesen Wolken leben und ziehen die Aufmerksamkeit sowohl von Himmelsfischern als auch von größeren Fleischfressern aus den Reichen darunter an.",
   erleben:["Himmelsfischer mit Netzen und Dreschkästen an langen Stangen, die die unteren Wolken durchpflügen","Ein plötzlicher Schub von unten, die Wellen brechen auf, als ein Grabender Rochen walartig himmelwärts schießt und eine ganze Wolke in einem Schluck verschlingt","Ein Tempest aus einem fernen Reich, der niedergeschlagen dasitzt, sein inneres Blitzen auf einem Tiefpunkt"]},
  {t:"Die Myzel-Aurora", x:"Wenn die Myconica schon selbst für die weiteren Wellen so ungewöhnlich ist, warum wird sie dann so stark befahren? Einer der Hauptgründe ist die unglaubliche Fülle pilzbasierter Ressourcen, die darauf wartet, von Alchemisten, Steeps und Chars gesammelt zu werden. Ein weiterer ist die Gelegenheit, die die untersten Abschnitte von Dimm bieten, nur einen Steinwurf von den Unter-Eaves entfernt. Wer aber Wunder sucht, findet die Myzel-Aurora: ein himmelwärts gespanntes Netz lebender Fäden, die beim Sonnenuntergang zu glühen beginnen und dafür sorgen, dass jede Nacht in der Myconica ein einzigartiges Schauspiel ist.",
   erleben:["Tauchboot-Crews, zurück von einem unmöglich tiefen Abtauchen, mit weit aufgerissenen Augen und Köpfen voller Geheimnisse","Das pulsierende Leuchten silbergrünen Lichts, das beim Sonnenuntergang vom Himmel Besitz ergreift","Eifrige Schnappsographen, ihre Bildfangkästen auf wackligen Pilzkappen aufgebaut, Sandwiches und Thermosflaschen mit heißem Tee an ihrer Seite, in Erwartung der perfekten Aufnahme von Dimms Mitternachtsschleier"]}
 ],
 erzaehl:[
  {p:259, x:"Die Myconica barg Geheimnisse, das wusste sie sicher. Sie konnte sogar verstehen, warum man sie noch nicht ausgehoben hatte, wenn man bedachte, dass man in manchen der Territorien, durch die sie gereist waren, wegen der Sporen nicht einmal die eigene Hand vor dem eigenen verdammten Gesicht sehen konnte. Was sie dagegen nicht verstand, trotz des Drängens ihres Navigators und der Entschlossenheit ihres Kapitäns, war, warum irgendeines dieser Geheimnisse es wert sein sollte, aufgedeckt zu werden.\nIhr Schiff war eine Insel der Ruhe, eine kleine Blase des Anorganischen inmitten eines Meeres aus Leben. Jede Fläche, über die sie fuhren, bewegte sich, als atme sie, eine Bewegung, die zugleich weniger ausgeprägt war als das Rauschen der Wellen, das sie ihr ganzes Leben lang gekannt hatte, aber unendlich beunruhigender.\nEiner aus der Unterbesatzung hatte sie neulich gefragt, ob es sich für sie wie Heimat anfühle. Sie war schließlich eine Gau. Sie hatte ihn gefragt, wie er sich fühlen würde, wenn er durch ein Meer aus Fleisch segelte, und hatte ihn seither nicht mehr an Deck gesehen."},
  {p:264, x:"Wie weit konnte man einer Seekarte wirklich trauen? Besonders einer, die so zerknittert und sporenverfleckt war wie diese, gezogen aus den Ruinen einer abweichenden Hochschaft-Cartoika (das Bauwerk selbst verlassen, von Gott-weiß-wem umgekrempelt und dem Verfall überlassen). Und einer, die mit so wenigen Federstrichen so viel andeutete, die mehr zu versprechen schien, als die Logik für möglich hielt.\nDoch ein Körnchen Wahrheit steckte bisher darin, soweit sie es beurteilen konnten. Eine dichte Pilzwelle, die sich wie eine Klaue nach Norden krümmte. Ein bleicher Geisterschaft im Südosten. Eine Bruchlinie durch Dimms Fleisch, in beunruhigender Genauigkeit aufs Papier gebracht, genau dort, wo die kleine Karte es sagte.\nUnd unter allem ein Fleck aus Grün – eine zweite Tinte, vielleicht aus Moos gewonnen, aufs Blatt getropft und von irgendeinem Kartografenfinger zu einem bedeutungsschweren Kreis verschmiert.\nDarunter war etwas, versprach sie. Etwas Neues."}
 ],
 geruechte:{p:261, t:"Gerüchte", x:[
  "Die wenigen, die die Wanderung durch Dimm’s Embrace überleben, leben für den Rest ihrer Tage wie Könige – auch wenn das weder öffentlich verkündet noch auch nur öffentlich anerkannt wird.",
  "Dimm wird mit den Jahren langsam bewusster, irgendeine Region tief in ihm organisiert sich selbst zu einer Form wahrer Sapienz.",
  "Die Grabenden Rochen waren nicht das Ergebnis crezzerinischer Mutation, sondern die Früchte der Arbeit eines örtlichen Alchemisten, der im Bund mit einer Gruppe Bestienhändler aus einem fernen Reich wirkte.",
  "Einmal im Jahr, an einem bestimmten Datum, schließt sich jeder der Schnappenden Blauen und öffnet sich dann abrupt wieder.",
  "Die Aurora der Myconica ist eine Himmelskarte, ein Protokoll der Orte, die der große, sich ausbreitende Pilz berührt hat, während er sich über die Grenzen des Reichs hinaus ausdehnt.",
  "An manchen Stellen kommen Dimms unterste Teile mit den Unter-Eaves selbst in Berührung.",
  "Die Myconica ist die Heimat der Gau, und die allerersten Mycosanctums wurden aus Pilzstücken geschmiedet, die aus einem damals jungen Pilz geschnitten wurden, der zu Dimm heranwachsen sollte.",
  "Die Wilden Tänzer sind weit klüger, als sie zunächst scheinen, und viele der unheimlichen Ausflüge ihrer Mitglieder haben ernste und einzigartige Zwecke, die bestehende Machtstrukturen stürzen oder die Zukunft ferner Länder ändern könnten.",
  "Foxfire und die Myzel-Aurora, an der es hängt, wachsen in direktem Gegensatz zu Dimm. Irgendwann, in Jahren, wird eines von beiden diesen gletscherlangsamen Wachstumskampf ‚gewinnen‘ und Meer wie Himmel für sich beanspruchen.",
  "Das erste Mitglied von Tiltwins Bande stammte aus der Myconica, nahm einen von tausend örtlichen Pilzen mit aus dem Reich und ließ ihn gedeihen und sich ausbreiten, mit so viel weniger direkter Konkurrenz."]},
 territorien:[
  {id:"dimms-embrace", t:"Dimm’s Embrace", typ:"Territorium", p:260,
   facts:[["Bewegung","Ständig, von der See wie vom Himmel"],["Ein Gefühl in der Luft","Von etwas unangenehm Zähflüssigem"]],
   x:"Das mit Abstand größte Territorium der Myconica: Dimm’s Embrace ist irgendwie zugleich das kargste und das lebendigste. Die „Wellen“ der Gegend sind eine einzige, sich ausbreitende Pilzmasse, eine Sammlung faseriger Ebenen, rülpsender organischer Schlote und glitzernder, augenartiger Knoten. Eingerollte Wedel zerren reflexartig an Reling und Kranleinen, und Schiffe, die auch nur in den am wenigsten crezzerdichten Gegenden über Nacht stillstehen, finden sich wahrscheinlich völlig aufgesogen, bis sie den Anker lichten können.",
   eintraege:[
    {t:"Der einzelne Atemzug", typ:"Bedrohung", x:"Auch andere Teile des Reichs haben ihre Gefahren, doch die Luft der Embrace selbst ist vielleicht die größte Bedrohung. Sporenschals sind für jeden Segler mit Lungen Pflicht, wenn er nicht zum Wirt einer von hundert virulenten Massen oder von Halluzinationen heimgesucht werden will. Tanks mit sauberer Luft und Rückatmungsgeräte sind noch besser.", i:"Und es gibt Gefahren auch für jene, die nicht atmen müssen, vom ständigen sichtverdeckenden Dunst bis zur schmutzigen Luft, die die Bewegungen selbst einer gut vorbereiteten Crew qualvoll träge macht."},
    {t:"Ein Grab der Anker", typ:"Bedrohung", x:"Einheimische warnen davor, ein Schiff in Dimm’s Embrace untätig liegen zu lassen, und diese Warnungen sind alles andere als zahnlos. Ein paar Minuten ohne Bewegung schaden kaum, auch wenn die Crew straucheln mag, wenn sich ihr Schiff aus dem wachsenden Pilzmorast um sie herum losreißt, um die Reise fortzusetzen. Ein paar Stunden, und es wendet sich drastisch zum Schlechten – die eingerollten Wedel, die einst verspielt wirkten, haben sich durch jede Tür und jeden Spalt hereingearbeitet, und jeder Augenblick, der mit dem Versuch verbracht wird, das Schiff zu befreien, ist ein weiterer Augenblick, in dem noch mehr Wuchs anwächst.", i:"Säume nicht in Dimm’s Embrace, denn sie klammert wie ein Kind und ist zu eifersüchtig, zu gedankenlos oder zu besitzergreifend, um loszulassen. Schiffe, die nicht eigens für das Queren von Dimm’s Embrace angepasst sind, müssen nach dem Ankerwerfen einen erfolgreichen Werte-Wurf ablegen, um wieder aufzubrechen, mit einem Abzug oder verringerter Wucht je nach der Zeit, die sie in Ruhe verbracht haben."},
    {t:"Schäfte wie gebrochene Knochen", typ:"Merkmal", x:"Muss eine Crew unbedingt rasten, ist es am sichersten, einen der Hochschäfte des Territoriums zu finden … oder das, was von ihnen übrig ist. Die gewaltige Masse von Dimm hat sie von Blättern entblößt, sich durch die Rinde gefressen und ihnen die Farbe entzogen, und diese geisterhaften Relikte der Macht der Verdanz sind nun kaum mehr als Grabsteine der Wellen, die einmal waren. Doch eines sind sie: fest. Der Eisenwurzel-Kern der noch stehenden bleibt stabil trotz der saugenden Fast-Wellen ringsum.", i:"Das Schiff an einen bleichen Schaft zu binden (oder, besser noch, es hochzuziehen, damit es an einem der gebrochenen Äste hängt), mag ein makabrer Weg zur Rast sein, aber ein wirksamer."},
    {t:"Oido’s Stone", typ:"Wunder, Kneipe", x:"Normalerweise wäre ein Segelstein kaum ein Wunder der Wellen, doch hier in der Embrace kann er sich wie ein Geschenk des Himmels anfühlen. Oido’s Stone ist ein Bergfragment, das mühelos durch das Myzelwachstum schneidet, geschmückt mit Suchscheinwerfern und Kränen. Obwohl Oido selbst kaum Einfluss auf die Richtung des Steins hat, genießen er und sein Gefolge den Ruf, festsitzenden Schiffen zu helfen, wo immer sie welche finden, sie aus dem Morast hinauf- und herauszuziehen und panischen Crews gutes, warmes Ale anzubieten.", i:"Die Getränke, die die auf dem Segelstein thronende Kneipe tatsächlich ausschenkt, sind von absolut furchtbarer Qualität, aber das scheint niemanden zu stören."},
    {t:"Die Wanderung", typ:"Merkmal", x:"Ein Ritual der Mitglieder der wenigen Gemeinschaften, die sich irgendwie im Territorium halten. Wenn jemand beschließt (oder bestimmt wird), die Wanderung anzutreten, wird er in Antipilz-Verbände gewickelt und mit Essig übergossen und dann zu Fuß ausgesandt, um eine andere Siedlung zu finden und Kontakt aufzunehmen.", i:"Das ist eine extrem schlechte Idee, und in den letzten hundert Jahren oder so haben nur eine Handvoll Wanderer ihr Ziel erreicht. Die meisten sterben mit Sicherheit, von Dimm verschluckt. Manche finden den Weg zu einem der Geisterschäfte der Region und leben allein auf dem ruinierten Stamm, bis Durst oder Raubtiere sie holen. Ein paar Glückliche werden von vorbeifahrenden Schiffen aufgelesen und heuern fast immer als Unterbesatzung an oder buchen Passage gegen das Versprechen von Arbeit, statt heimzukehren."},
    {t:"Der Umarmung entkommen", typ:"Hinweis", x:"Die Notwendigkeit ständiger Bewegung beim Queren von Dimm’s Embrace schreckt viele Crews ab, und viele Besucher der Myconica bleiben innerhalb der (relativ) sicheren Grenzen der äußeren Territorien. Einheimische Alchemisten und Rattlehands treiben guten Handel damit, Crews, die tiefer vordringen wollen, mit Anpassungen für ihr Schiff zu versorgen, die eigens gegen einige der gefährlicheren Aspekte der Region entworfen sind – und auch bestehende Umbauten für das Fliegen und für das Abtauchen tief unter die rauschenden Wellen können einem Schiff in diesen Lagen helfen."},
    {t:"Essigwäsche", typ:"Zusatz, 1 Einsatz", x:"Einfach, aber wirksam: Das Deck des Schiffs ist mit Essigfässern gesäumt, die nach einer Nacht vor Anker über die Reling entleert werden können. Die Flüssigkeit ist ein natürliches Pilzabwehrmittel, das die über Nacht angewachsenen Wedel und Auswüchse austrocknen und zurückweichen lässt. • Einmal pro Reise kannst du nach dem Ankerwerfen wieder losfahren, ohne Abzug oder Wuchtverlust. • Das Auffüllen der Essigfässer im Hafen kostet die Crew wahrscheinlich etwas Bergegut (falls ein Hafen überhaupt die Einrichtungen hat, um zu helfen)."},
    {t:"Raupenketten", typ:"Biss, 3 Einsätze", x:"An mehreren Abschnitten des Außenrumpfs angebracht, beißen sich diese Ketten in das Material von Dimm’s Embrace und geben einem Schiff weit mehr Halt, wenn es sich vom Wuchs der Ankerzeit losreißen will. Auch wenn sie in laubreichen Gegenden weniger wirksam sind, haben sie auch außerhalb des Reichs ihren Nutzen. • Sägen +1 • Erlaubt dir, nach dem Ankerwerfen weiterzufahren, ohne Abzug oder Wuchtverlust."},
    {t:"Bestehende Vorteile", typ:"Verschieden", x:"Je nachdem, wie ein Schiff bereits gebaut ist, kann die Fahrt durch die Embrace deutlich weniger mühsam sein. Gassäcke und Auftriebssysteme sind für den örtlichen Luftverkehr wegen Navigationsproblemen vielleicht nicht sehr nützlich, können ein Schiff aber kurz nach oben ziehen, wenn es Wuchs abschütteln muss. Auch Druckhüllen von Tauchbooten und Luftfiltereinheiten halten das Schlimmste der Giftigkeit der Luft wirksam fern."}]},
  {id:"blue-banxa", t:"Blue Banxa", typ:"Randterritorium", p:261,
   facts:[["Spinnenjagd-Saison","Winter"],["Örtliche Wörter für Blau","Nur eines, in jeder Sprache und jedem Tonfall gleich"]],
   x:"Eines der wenigen Gebiete der Myconica, in denen Dimm von einheimischer Flora überwuchert wurde: Die Eisenwurzeln von Banxa beherbergen eine ganz andere Art von Pilz. Diese Bäume sind stark, gesund und in jeder Hinsicht normal bis auf ihr Laub; statt des üblichen Wildsee-Grüns tragen die Äste Tausende von Pilzen, die offenen Muschelschalen gleichen, außen schwarz und verkohlt wirkend, innen blassblau.",
   eintraege:[
    {t:"Die Schnappenden Blauen", typ:"Merkmal", x:"Obwohl die Pilze von Blue Banxa weit entfernt vom Laub der weiteren Wellen sind, tragen sie Schiffe und Siedlungen auf dieselbe Weise. Auch ihre Größen schwanken stark: Manche Äste sind mit Hunderten besetzt, andere hängen unter dem Gewicht von ein oder zwei titanischen Exemplaren durch.", i:"Die Offenmaul-Form der Schnappenden Blauen mag beunruhigen, doch die Pilze selbst sind gefahrlos zu befahren (auch wenn sie als Nahrung kaum nahrhaften Gehalt haben)."},
    {t:"Verwerfungsspinnen", typ:"Bedrohung", x:"Wo immer einzigartige Ökosysteme bestehen, steigen Raubtiere auf, um sie in wirksame Jagdgründe zu verwandeln. An der Spitze der Nahrungskette von Blue Banxa steht die Verwerfungsspinne, ein riesiges Spinnentier mit einem Hinterleib, der einem der Schnappenden Blauen gleicht. Kommt ein Schiff zu nah oder fährt gar über die lauernde Spinne hinweg, schlägt das „Maul“ im Hinterleib des Spinnentiers zu, und der Hauptkörper der Spinne krümmt sich herum und pickt gestrandete Wildsegler einen nach dem anderen heraus.", i:"Verwerfungsspinnen meiden meist Schiffe, deren Entwurf Kettensägen enthält, da das Einfangen eines solchen Fahrzeugs meist mehr Schaden anrichtet, als eine frische Nahrungsquelle wert ist."},
    {t:"Monday Morning", typ:"Schattenquelle", x:"Die Besitzer von Monday Morning behaupten, die saphirblaue Flüssigkeit in ihren Becken (gewonnen durch Ernten und Auspressen der Pilze der Region) habe eigentümliche, mystische Regenerationskräfte.", i:"Hat sie nicht, abgesehen vom üblichen Nutzen eines guten Bads und etwas Zeit zum Entspannen."}]},
  {id:"clacker-jack", t:"Clacker-Jack", typ:"Randterritorium", p:261,
   facts:[["Entfernung zum Zentralknoten","Veränderlich, je nach den sprunghaften Bewegungen des Knotens"],["Gespeicherte Energie pro Kappe","600–800 Mycovolt"]],
   x:"Das Haska-Netzwerk durchzieht jedes Reich, heißt es, ein Informationsaustausch über schleimige Stränge. Manche behaupten sogar, den Zentralknoten gesehen zu haben, wie er sich hangelnd auf pulsierenden Ranken durch die Senke bewegt. Doch jedes Netzwerk braucht eine Energiequelle, und es ist das summende Potenzial von Clacker-Jack, das diese Stränge über unzählige Meilen speist.",
   eintraege:[
    {t:"Also dahin gehen die Stürme", typ:"Merkmal", x:"Die Pilze von Clacker-Jack sind weit traditioneller als der meiste Wuchs der Myconica: rollende Wellen aus dicken, blassen Stielen und bunten Kappen. Auch der Himmel ist traditioneller – über den größten dieser Pilze, die fast die Höhe von Hochschäften erreichen, verdunkeln und gleißen Wolken, und Blitze schlagen immer wieder in ihre Kappen ein.", i:"Diese Blitzeinschläge seien die Quelle der Energie des Haska-Netzwerks, sagen die Einheimischen. Wie viel Wahrheit in dieser Aussage steckt, sei dahingestellt, doch offensichtlich sind die Pilze hervorragende natürliche Speicher für voltaische Energie – wer sich einem der Stiele nähert, dem klingeln wahrscheinlich die Zähne, und das Haar (falls vorhanden) schwillt zu einem Puschel an."},
    {t:"Unterkappen-Städtchen", typ:"Hafen", x:"Im ganzen Territorium Clacker-Jack gibt es keinen Hafen, der größer wäre als eine Kleinstadt, aus Furcht, größere Bauwerke könnten verirrte Blitze von ihrem eigentlichen Ziel ablenken. Stattdessen haben viele der Kappen kleine Hafenstädtchen in ihrem Schatten, sicher vor dem Zorn des Himmels und mit unbegrenzter örtlicher Energie versorgt.", i:"Die Bewohner dieser Städtchen haben sich im Lauf der Jahre an die stark geladene Umgebung angepasst und bemerken kaum, dass ihre Heimstätten um riesige lebende Batterien gedrängt stehen."}]},
  {id:"foxfire-ocean", t:"The Foxfire Ocean", typ:"Verstecktes Territorium", p:264,
   facts:[["Farben bei Nacht","Das angelaufene Silber eines alten Schlüssels und das Grün verlorener Blätter, wachsamer Augen, brennender Zukünfte"],["Farben bei Tag","Das weiche Gold verschütteten Whiskeys und das Violett eines gebrochenen Herzens, einer gespaltenen Geode, eines sich ausbreitenden Blutergusses"],["Myzelverbindungen","Weniger als die Dicke eines Ektus-Arms"]],
   x:"Viele nehmen an, dass die gewaltige Pilzprobe mit der weiten Ausbreitung Dimms anstelle des üblichen Laubs und Astwerks von Gestrüpp und Geflecht den ganzen Weg bis hinunter zu den Eaves reicht. Und in manchen Fällen haben sie recht – es gibt sehr, sehr viele Stellen an der Oberfläche, an denen man, wenn man lange genug bohrte, durch Schicht um Schicht immer dichteren Pilzes dränge, bis man eine letzte Membran durchbräche und hilflos in die erstickende Dunkelheit des längst verlorenen Bodens stürzte.\nDoch wenn man gut gewählt hätte oder die Art Seekarten besäße, von denen viele an der Oberfläche schwören würden, dass es sie nicht gibt …\nDann fände man das höhlenhafte Wunder des Foxfire Ocean.",
   eintraege:[
    {t:"Ein Meer unter dem Meer", typ:"Merkmal", x:"Der Foxfire Ocean ist eine Ansammlung von Kammern, manche in einem Tag zu durchqueren, andere erst in Wochen, die sich planlos unter Dimms Masse ausbreiten. Sie sind so vielfältig, wie die Wellen darüber einheitlich sind – eine mag voller gigantischer Giftpilze sein, eine andere voll herabhängender Salamandermähne, wieder eine andere voll Stinkmorcheln, Maitake und Morcheln. Die Luft in den Höhlen ist keineswegs sporenfrei, aber klarer und kühler als die Luft darüber. Sie riecht nach Dunkelheit und Erde. Sie seufzt vor Frieden.", i:"Es ist fast unmöglich, den Foxfire Ocean ohne Tauchboot zu erreichen, und der Druck, der entsteht, wenn man durch Dimms erdrückende Masse hinabschneidet, ist unglaublich … Doch wenn Crews die Weite darunter erfolgreich erreichen, sollten Druck-Leisten gelöscht und Druckfolgen gemildert oder aufgehoben werden. Die Aufmerksamkeit hingegen …"},
    {t:"Der Totholzmond", typ:"Wunder, Schrecken", x:"Er hängt im Zentrum der Unterpilz-Weite, meilenbreit und in phosphoreszierendem Licht brennend. Der Mond ist künstlich, gespeist von Holzgaben aus nah und fern, geliefert von Luftschiffen, die nie den Himmel gesehen haben. Wie er dort unverankert hängt, ist ein Rätsel, das nur wenige zu hinterfragen wagen, damit die Wirklichkeit sich nicht ihrer grundlegenden physikalischen Gesetze erinnert und das gesamte Gebilde auf den Grund des Ozeans stürzen lässt.", i:"Obwohl er, wie der Name sagt, aus totem Holz gebaut ist (verzehrt vom glühenden Pilz, der den Ozean bei Tag und bei Nacht erleuchtet), kann der Mond Besuchern gegenüber beunruhigend wachsam wirken. Möglicherweise gelten hier die Regeln zur Aufmerksamkeit, doch was der Mond versuchen könnte, wenn eine Crew seine Aufmerksamkeit erregt, ist etwas, das du selbst herausfinden musst."},
    {t:"Ein so langsamer Krieg", typ:"Merkmal", x:"Der Mond ist in mehr als einer Hinsicht ein Paradox. Manche weisen darauf hin, dass seine Pilzfarben die Myzel-Aurora, die den Himmel darüber erleuchtet, nachahmen (oder vielleicht deren Quelle sind), und dass dort, wo das Mondlicht am stärksten ist, die freiliegenden Innenflächen von Dimm bröckelig und verkalkt wirken.", i:"Könnte man einer der beiden Wesenheiten Bewusstsein zuschreiben, würde man meinen, sie lägen in einem Kampf auf geologischer Skala. Vielleicht triumphiert eines Tages eine von ihnen."},
    {t:"Totholzbauern", typ:"Merkmal", x:"Bewohner des Ozeans, die ihr Leben damit verbringen, zur Lichtquelle der Höhle beizutragen; jedes ihrer Schiffe ist eine Mischung aus Luftschiff und Tauchboot. Manche tauchen tiefer ab und stehlen Rinde von den freiliegenden Stämmen in der lichtlosen Tiefe. Andere ziehen weiter hinaus in Reiche, die noch voller Holz und Laub sind, um ihre crezzergespeiste Beute zurück in die Myconica zu schleppen.", i:"Viele dieser Bauern entwickeln Sinne und Fähigkeiten, die selbst die Arconauten des Foxfire Ocean überraschen, und behaupten, ihre Segnungen kämen direkt vom Mond über ihnen, um ihnen bei ihrer Aufgabe zu helfen. Wie so vieles in der Myconica darf man ihre Behauptungen über die Quelle ihrer Gaben mit Skepsis betrachten, doch ihre Wirksamkeit ist nicht zu bestreiten."}]}
 ],
 haefen:[
  {id:"kilderkin-majestic", t:"The Kilderkin Majestic", typ:"Schiff", p:262,
   facts:[["Anzahl der Pilz-Ballsäle","26, davon 25 mit eigener Band"],["An der Tür abgegeben","Sporenschals und Sauerstofftanks, getauscht gegen die aktuellen Moden der Kilderkin"]],
   x:"Das Schiff atmet Musik. Ballsäle wogen vor Tänzern in zerlumptem Putz. Die trübe Luft flackert vor Phosphoreszenz, hallt von Rufen und Lachen wider und ist erfüllt von den kräftigen Gerüchen von Verfall, Schweiß und teurem Duft. Gibt es irgendwo einen einladenderen Ort, einen, der weniger urteilt und mehr akzeptiert? Wenn ja, haben die Tänzer ihn nicht gefunden.\nDie Feier auf der Kilderkin Majestic begann vor einem Jahrhundert und zeigt keine Anzeichen, nachzulassen. Das Schiff selbst ist eine Ruine, ein Schatten seiner einstigen Seetüchtigkeit – es dampft betrunken über die Pilzflächen, verliert manchmal ein Eisenblech oder einen Holzspant, wenn es einen besonders schwierigen Anstieg nimmt oder durch einen sprießenden Wuchs pflügt, doch solche Katastrophen bremsen es kaum.\nEs mag einmal ein Frachter gewesen sein, nach den riesigen Innenräumen zu urteilen (nun umgebaut zu Ballsälen, Festhallen und Kampfgruben). Es mag ein uraltes Meer befahren haben (denn die zuckenden Tentakelmassen, die es unablässig vorantreiben, sind eindeutig von der Myconica, und kein anderer Biss, der für Baumkronenwellen irgendeiner Art geeignet wäre, ist zu sehen). Und es mag, wenn man dem atemlosen Flüstern eines sporentrunkenen Tänzers oder dem hingekritzelten Zettel glaubt, den einem eine vorbeihuschende Gestalt in einem schwach beleuchteten Korridor in die Hand drückt, einen anderen Zweck als das Vergnügen haben (wobei das niemand offen zugeben wird, bis man sich in die höchsten Kreise der Kilderkin-Gesellschaft vorgearbeitet hat, wo der Tanz zu einem köstlichen Ränkespiel und dringlicher politischer Machenschaft wird).\nEines ist jedenfalls sicher – holt eure besten Schuhe, atmet tief durch, und ihr werdet eine verdammt gute Zeit haben.",
   eintraege:[
    {t:"Die Schalmaskerade", typ:"Merkmal", x:"Persönliche Atemgeräte sind innerhalb der Majestic verboten und werden an den Türen höflich entfernt oder grob beschlagnahmt. An ihrer Stelle erhalten Besucher zweierlei – eine Marke für die Rückgabe beim Verlassen des Schiffs und eine Kilderkin-Schal-und-Maske-Kombination, zugeschnitten nach der Mode, die gerade das Schiff erfasst.", i:"Kilderkin-Schals verhalten sich zu einem Sporenschal wie ein sonniger Tag zu einem Sturm, ein vollständiger Gegensatz, der den Begriff sauberer Luft verhöhnt. Sie blocken schlechte Luft und treibende Sporen nicht so sehr, wie sie sie einladen, aber in so großer Vielfalt, dass sich keine einzelne symbiotische Besiedlung festsetzen kann – Träger spüren eine pilzige Euphorie, die weiter wächst, solange der Schal getragen wird, und die extrem schwer aufzugeben ist."},
    {t:"Der Rülpsschlot", typ:"Wunder, Schrecken", x:"Ein riesiger Schornstein, der die Mitte der Decks der Kilderkin beherrscht und unablässig unmögliche Mengen warmer, feuchter Sporen aus den Wellen emporbläst, durch die das Schiff pflügt. Obwohl er leicht schief steht, ist der Schlot stabil genug, dass Hütten und Zelte rings um seine Außenseite gespannt wurden, als Orte kurzer Rast für jene an Bord, die zu müde zum Tanzen sind.", i:"Der Fuß des Schlots, tief im Schiff, ist mit Netzen bespannt, um benommene Tänzer aufzufangen, die weit oben vom Rand springen und auf den Sporenwolken in einen sonst sicheren Tod hinabsurfen."},
    {t:"Wechselnde Moden", typ:"Merkmal", x:"Nicht nur der Stil der Gewänder und die Art der Musik wandeln sich im Lauf des Jahres, während der Tanz weitergeht, sondern auch die Unterhaltung, die Besuchern geboten wird. In manchen Jahreszeiten sind die Tänze schnell und enden nur durch die reine körperliche Erschöpfung der Tänzer, und Ironbound-Köche servieren importiertes Fleisch, getränkt in belebenden Gewürzen. In anderen sind die Ballsäle blutbespritzt, Tänzern werden Messer und Ketten zum Wirbeln gereicht, und die Mezzanine füllen sich mit jenen, die Spektakel nicht scheuen und wettlustig sind.", i:"In manchen Jahreszeiten geruhen die Besitzer des Schiffs, die Hohen Majestäten, selbst am Tanz teilzunehmen – sie wirbeln mit ebenso unsicherer Eleganz wie die übrigen Gäste, Flüstern zupft an ihren Kleidern."}]},
  {id:"the-first", t:"The First", typ:"Mycosanctum", p:262,
   facts:[["Baumaterialien","Tote Schiffe, morsches Holz, Dimms eigenes Fleisch"],["Die Wahrheit hinter dem Namen","Fraglich"]],
   x:"Obwohl es darüber viel Streit gibt, behaupten die Bewohner von The First, ihr Name sei zutreffend – die rollende Masse aus Wracks und Pilz, die sie ihr Zuhause nennen, sei das allererste Gau-Mycosanctum, der Ursprung der gesamten Blutlinie.",
   eintraege:[
    {t:"Ein mobiler Hafen", typ:"Merkmal", x:"Wie die meisten Mycosanctums ist The First ebenso sehr ein frei umherziehendes Wesen (oder ein Schiff aus eigenem Recht) wie ein Hafen. Es quert die weiten Flächen von Dimm’s Embrace mühelos und hält an und fährt an, wie es ihm beliebt.", i:"Dass der Hafen aus genau demselben Pilz gebaut ist, den er überquert, hält ihn frei von aufdringlichem Wuchs, auch wenn er weiterhin anderen, örtlicheren Problemen gegenübersteht."},
    {t:"Das Keuchen", typ:"Bedrohung", x:"Die Luft im Mycosanctum ist weit sauberer und sicherer als die der Wellen draußen, aber auch weit feuchter. Bei den meisten lungenbesitzenden humanoiden Wesen führt das zu nichts Schlimmerem als einem hackenden Husten, der nach ein paar Tagen außerhalb des Inneren des Mycosanctums abklingt, doch für Ironbound (normalerweise glücklich immun gegen verschiedene Luftprobleme) gibt es zusätzliche Gefahren zu bedenken.", i:"Etwas in der Feuchtigkeit der Luft beginnt Ironbound zu verlangsamen, ob sie nun aus Holz, Metall oder fremderen Stoffen bestehen. Vielleicht ist es eine Erwärmung der bloßliegenden Seele und keine körperliche Wechselwirkung mit ihren Materialien, doch verankerte Besucher scheinen problemlos durchzukommen."},
    {t:"Der Junge Rat", typ:"Anführer", x:"Die Kontrolle über The First liegt traditionell bei der jüngsten Generation von Gau, die darin aufgewachsen ist, mit der Begründung, dass ihre Jugend und Unschuld ihnen eine Klarheit verleiht, die den Alten fehlt.", i:"Obwohl diese Philosophie einige offensichtliche Probleme hat, erhält der Junge Rat Unterweisung und Rat von älteren Mitgliedern. Wenn sie Entscheidungen treffen, sind diese tendenziell überraschend reif und ausgewogen."}]},
  {id:"port-nycol", bild:["figur/myconica_port-nycol",616,712], t:"Port Nycol", typ:"Hafen", p:263,
   facts:[["Preis des Redens auf den Märkten","Zwei Kisten Fracht und ein Vorgeschmack auf die Jag-Geißel"],["Örtliche Sporenhunde","Todesstill und übermäßig tentakelig"]],
   x:"Etwas am Geisterschaft von Nycol bringt die Nerven zum Klirren, bringt Seeleute zum Zähneknirschen. Vielleicht ist es die Reise zum Hauptort, eine Reihe wackliger Aufzüge, die von einem Riss im Pilzgestrüpp hinab in zerfranzte Tiefen führen (eine Reise, die die meisten Crews zwingt, ihre Schiffe Hunderte Fuß über sich zurückzulassen, während sie hinabsteigen). Vielleicht sind es die stillen Märkte der mittleren Regale, betrieben von Ketra- und Tzelicrae-Händlern, auf denen alle Geschäfte schriftlich gemacht werden und nie ein Wort fällt. Oder vielleicht ist es der Schaft selbst und der ständige Geruch langsam faulenden Holzes, der das Gefühl gibt, der ganze vielstöckige Hafen könne jeden Augenblick abrutschen oder brechen.\nWas immer es ist, Crews verbringen meist so wenig Zeit wie möglich in Nycol, verlassen es aber unweigerlich mit dem, was sie suchten.\n… Es sei denn, das, was sie suchten, war Behaglichkeit, dann gehen sie mit leeren Händen.",
   eintraege:[
    {t:"Die Stillen Märkte", typ:"Merkmal", x:"Wenn man sich an die Eigenart gewöhnt, ausschließlich schriftlich zu handeln und zu feilschen, sind die Stillen Märkte tatsächlich ein fantastischer Ort, um Fracht loszuwerden und Ressourcen und Kuriositäten aus den Wellen ringsum zu finden. Jede Ebene des Marktes hat ihre Spezialität, aber eines bietet keine davon öffentlich an: Flüstern.", i:"Das heißt nicht, dass man sie nicht finden kann – man muss nur wissen, wo man suchen muss und welche Handflächen man schmieren muss."},
    {t:"Scrimshaw-Gassen", typ:"Merkmal", x:"Die Straßen und Gassen von Nycol sind direkt in die Pilzregale gehauen, auf denen sie stehen, und während die Märkte an der Oberfläche liegen, sind die Wohnungen von innen ausgehöhlt.", i:"Die erfolgreichsten Händler erwerben einen Platz im Stamm des Schafts selbst und sind von ihresgleichen am starken Geruch nach Laubmoder und sterbendem Holz zu unterscheiden."},
    {t:"Regal um Regal", typ:"Merkmal", x:"Nycol ist eine ausufernde Siedlung, gebaut über viele Schichten von Konsolenpilz, verankert an einem einzelnen verkümmerten Hochschaft, und jedes Regal trägt sein eigenes Städtchen oder seinen eigenen Markt. Manche sind einladender als andere, und je tiefer man kommt, desto lebhafter werden sie (denn Rufe und Lachen halten die Dunkelheit gut zurück), doch man spürt, dass jede Gemütlichkeit ihren Preis hat.", i:"Es gibt nur wenige Orte in der Myconica, an denen Gau die Mehrheit der Bevölkerung stellen, aber in Nycol fehlen sie fast völlig."},
    {t:"Hyacinth", typ:"Schattenquelle", x:"Niemand scheint zu wissen, was eine Hyazinthe ist, aber die Quelle hat den einzigartigen Ruf, einer der am wenigsten entspannenden Orte des Hafens zu sein. Eingelassen in das Innere des untersten Regals und benebelt mit Erinnerungen an Pflanzensaft, können Wildsegler erwarten, prekär zu sitzen, die Füße über dem Spalt darunter baumelnd, ohne eine Spur von Halteseilen oder Sicherheitsnetzen.", i:"Einheimische gehen nicht nach Hyacinth, um sich zu entspannen – sie gehen dorthin, um in Privaträumen Geschäfte zu machen, wo Worte frei fließen und verbotene Themen zur Sprache kommen können."}]},
  {id:"gilliham-gladeside", t:"Gilliham’s Gladeside", typ:"Hafen", p:265,
   facts:[["Wachtürme von Gladeside","Mit Ballisten und Kettenkanonen bestückt, um heranrasende Schiffe zu bremsen"],["Gillihams Leitspruch","„Wachstum ist ein natürliches Verlangen, und Blühen das vollkommene Ende“"]],
   x:"Gladeside beherrscht eine ganze Höhle des Foxfire Ocean (mit Besitzungen in zwanzig nahen Kammern) und ist mit Abstand der größte und einflussreichste Hafen der Region. Obwohl es eine geschäftige Stadt mit blühendem Nachtleben enthält und Besuchern viele Möglichkeiten bietet, die örtlichen Sehenswürdigkeiten zu genießen (etwa den Zoetrop-Jahrmarkt, die wöchentlichen Verkostungen, das Denkmal für Nie-Dimm und das Mondschatten-Theater), ist es am besten bekannt für die Ackerflächen, die es umgeben, und die Ernte, die sie bieten.",
   eintraege:[
    {t:"Parasitenlichtungen", typ:"Merkmal", x:"Pflanzen der Gestrüpp-Ebene bei Licht eines künstlichen Mondes in einem Raum ganz ohne Erde anzubauen, ist keine leichte Aufgabe. Doch die Parasitenbauern der Lichtungen sind ein ehrgeiziger Schlag und haben sich der Herausforderung mit Genuss und Eifer gestellt.", i:"Schiffe queren viele Höhlen, um mit Obst, Kräutern und Gemüse aus den Parasitenlichtungen zu handeln, den gestohlenen Geschmäckern ferner und hoher Wellen."},
    {t:"Der Beschlagnahme-Käfig", typ:"Bedrohung", x:"Es ist eine einfache Regel, Leute – pflügt Schiffe nicht geradewegs durch die Parasitenfarmen! Sie steht auf Schildern, wird aus Lautsprechern am Hafenrand geblärrt, wird von Wachen hektisch signalisiert, sobald sie sich nähernde Schiffe sehen … Aber hin und wieder poltert eine rücksichtslose Crew geradewegs in die Wuchszonen, und es muss eine Art Strafe verhängt werden.", i:"Der Beschlagnahme-Käfig ist ein riesiger Stinkmorchel-Pilz, dessen natürliches Netz hervorragende Pilzgitter bildet, die verhindern, dass hineingeschleppte Schiffe wieder herauskommen, bevor ihre Crews Buße getan haben. Diese besteht meist aus Zwangsarbeit in den Hainen und verpflichtenden Aufklärungsgipfeln."},
    {t:"Wuchsmeister Gilliham", typ:"Anführer", x:"Ein stämmiger, fröhlicher Ektus mit knochenweißen Blüten, dessen freundliches Auftreten einen Willen von absolutem Eisen verbirgt.", i:"Gilliham war viele Jahre Gärtner auf den Wellen darüber, und nach seinen Entwürfen sind die Lichtungen angelegt."}]},
  {id:"salamander-strut", t:"Salamander Strut", typ:"Hochhafen", p:265,
   facts:[["Beeinträchtigte Bottiche","Einer (aber sprich nicht über den einen)"],["Beliebte örtliche Gebräue","Schlachtmelonen-Rausch, Reines Tankside, Bitteres Grinsen, Prallwasser"]],
   x:"Eine Reihe metallener Laufstege und riesiger Wassertanks, angeschraubt an den Dachraum einer der größeren Höhlen, so weit vom Mond entfernt, dass sie sich mehr auf das Licht gefangener Glühwürmchen verlässt als auf das Leuchten des Ozeans.\nWenige Menschen leben auf dem Strut, doch die, die es tun, sind hingebungsvoll – die gesamte Anlage ist eine der wenigen Quellen gefilterten Wassers für das Unter-Reich, sammelt verseuchte Flüssigkeit und presst sie durch eine Reihe chemischer Bottiche und Erhitzungsprozesse, bevor sie zu den Pilzwellen darunter hinabgeschickt wird.",
   eintraege:[
    {t:"Salamanderbart", typ:"Merkmal", x:"Eine Art stalaktitenähnlicher Wedel, die neben dem Strut herabhängen, jeder triefend von Wasser, das aus Dimms Innerem gesogen wurde.", i:"Direkt an der Quelle zu trinken, ist eine wenig vernünftige Idee."},
    {t:"Mild Forth Place", typ:"Kneipe", x:"Die einzige Kneipe von Salamander Strut, die zugleich als Wohnquartier für alle dort arbeitenden Alchemisten und Ingenieure dient. Für Wildsegler gibt es nicht viele Einrichtungen, auch wenn mehrere Luftschiff-Festmacherpfosten von der Kellerebene abstehen, doch der Ort ist bekannt für Qualität und Vielfalt der angebotenen Getränke.", i:"Genau genommen bietet die Bar der Kneipe nur Wasser an, aber sie aromatisieren und füllen das Zeug auf Weisen ab, wie viele Wildsegler sie noch nie gesehen haben. Alle in Mild Forth Place servierten Getränke haben den Marker Heilend."}]}
 ],
 fraktionen:[
  {id:"wilde-taenzer", bild:["figur/myconica_wilde-taenzer",399,974], t:"Die Wilden Tänzer", p:266,
   facts:[["Heimatrevier","Die Kilderkin Majestic"],["Motivation","Die Welt vergessen"]],
   x:"Der Tanz zieht Menschen aus allen Lebenslagen an, doch Wildsegler sind es, die am längsten bleiben. Für die meisten ist es die fehlende Verbindung zu den weiteren Wellen, die sie anzieht, die Chance, wirklich abseits der ständigen Arbeit des Reisens und Entdeckens zu sein, die so viel von ihrem Leben ausmacht. Einen Ort zu finden, an dem sie sich einfach gehen lassen können, einen Ort, an dem die Gefahren verstanden und einkalkuliert sind und an dem Essen und Wein frei fließen … nun, man kann ihnen nicht verübeln, ihn für eine Art Himmel zu halten.\nWenige Wilde Tänzer gehen. Die, die es tun, finden meist schon bald wieder zurück.",
   grundsaetze:{intro:"Nicht niedergeschrieben – lediglich wahr.", x:["Lass dich von der Musik tragen.","Atme tief und sei frei.","Lass die Nacht nie enden."]},
   nsc:[{n:"Chime Towerfoot", b:"Ketra", x:"Ein uralter Tänzer mit Knochen aus selbst gewachsenem Pilz. Chime bevorzugt die offene Luft der oberen Decks gegenüber den engen Räumen darunter."},
        {n:"Alya", b:"Itzenko", x:"Mit jeder Häutung bekommen sie mehr Gelenke zum Arbeiten und mehr Formen, in die sie sich winden können."},
        {n:"Hraoked Geil", b:"Gau", x:"Grimmig und still, durchstreift Geil die Hallen und Gänge der Kilderkin auf der Suche nach ihrer vermissten Crew. Der wilde Tanz hat keine Macht über sie, und die Tänzer selbst scheinen instinktiv zu wirbeln, sich zu winden und vor ihr zurückzuscheuen."}],
   haken:["Ein Modewechsel bringt den Bedarf an fremden Pelzen gefährlicher Bestien.","Die Kilderkin nähert sich Blue Banxa, und die Musik in jedem der Ballsäle wechselt zu etwas Militärischerem und Stolzem.","Besuchende Wildsegler bringen Kitesails mit und lösen damit eine Mode des Lufttanzes inmitten der Dämpfe des Rülpsschlots aus.","Eine neue Krankheit befällt die Tänzer, etwas, das ihre Schals nicht herausfiltern können. Oder vielleicht, das ihre Schals einladen …?","Die Musik verstummt. Der Tanz ist vorbei. Etwas ist schiefgegangen.","Tänzer beginnen, sich über die Reling zu stürzen, und faseln vom „Gold und Grün“ darunter."],
   eintraege:[
    {t:"Juice Povay", typ:"Anführer", x:"Kein tatsächlicher Anführer in irgendeiner Weise, aber dennoch eine berühmte Gestalt. Weithin als der Wildeste der Tänzer angesehen; mit Juice Schritt zu halten, ist eine Übung in Wahnsinn.", i:"Der Ironbound hat seit über einem Jahr keine Pause von den Feierlichkeiten gemacht und seit mehreren Monaten keinen Schritt verpasst."},
    {t:"Wein lungenweise", typ:"Merkmal", x:"Gebraut in einem Brenn- und Gärverfahren, das den Uneingeweihten arkan erscheint, werden die sporenversetzten Weinflaschen, die an die Tänzer ausgegeben werden, ebenso sehr eingeatmet wie getrunken.", i:"Manche trinken durch ihre Schalmaskerade-Masken, wobei viele der Verzierungen eigens für diesen Zweck mit Löchern für Mund und Nase versehen sind."},
    {t:"Der Alte Maschinenraum", typ:"Zerlegestation", x:"Was immer die Tentakel antreibt, die die Kilderkin bewegen, es hat nichts mit dem Maschinenraum zu tun. Der Raum dient nun als Metzgerei und Zubereitungsbereich für die ständigen Bankette, die die Tänzer am Tanzen halten.", i:"Die dicken Wände und die gut gewarteten Lüftungssysteme sorgen dafür, dass Feiernde, die sich zur Zerlegestation hinabwagen, manchmal ein wenig ihres Zeit- und Weitblicks zurückgewinnen."}]},
  {id:"hohe-majestaeten", bild:["figur/myconica_hohe-majestaeten",430,938], t:"… und die Hohen Majestäten", p:267,
   facts:[["Heimatrevier","Der Kommandoturm der Kilderkin Majestic"],["Motivation","Den Tanz zu nähren und gewisse Feiernde für einen weit revolutionäreren Walzer zu säen"]],
   x:"Sind dies die ersten Tänzer der Kilderkin oder vielleicht die ursprüngliche Crew? Spüren sie denselben myconischen Takt wie der Rest des Schiffs, oder sind sie durch die Nähe taub dafür, oder treibt er sie stärker an als ihre eigenen Herzen? Schwingen und drehen sie sich noch, dort oben im Kommandoturm des Schiffs?\nDas sind die Fragen, die Besucher stellen, wenn sie des Tanzes müde werden, falls sie je gehen können.\nEs sind die falschen Fragen.",
   grundsaetze:{intro:"Obwohl die Tänzer der Kilderkin allein vom Rausch des sporengetriebenen Tanzes angetrieben werden, haben die Majestäten, die das Schiff kontrollieren, Beweggründe von weit größerer Tragweite und schrecklicherer Klarheit.", x:["Unterwandern – Besucher in den Schoß des Tanzes holen.","Einschleusen – sie durch Spore und Schweiß und Freude im Netz der mykomesmerischen Agenten fangen.","Destabilisieren – wenn die Zeit reif ist, die Agenten wecken, um Chaos zu säen und ferne Mächte zu stürzen."]},
   nsc:[{n:"Garland", b:"Ardent", x:"Tanzende und schlemmende Person; die Schalmaskerade-Maske zeigt ein weinendes Kind. Redet endlos darüber, wie viel Spaß sie hat, während die Tränen fließen."},
        {n:"Dask Fornell", b:"Mothryn", x:"Ein ahnungsloser Agent; Dask hat es geschafft, sich von der Majestic loszureißen, fühlt sich aber seither nicht mehr ganz wie sie selbst."},
        {n:"Six Oh Three", b:"Ironbound", x:"Einst ein Char, nun Koch der Majestäten selbst. Hört mehr von den Geheimnissen hinter dem Tanz, als gut ist."}],
   haken:["Der Kommandoturm wird von einer Explosion erschüttert, wankt, stürzt aber nicht. Was hat das getan?","Flüstern von den wenigen, die sich vom Tanz losreißen, von großen Plänen und sich ausbreitendem Verfall und Blut in fernen Straßen.","Eine der Hohen Majestäten verlässt das Schiff zum ersten Mal seit vielen Jahren.","Agenten beginnen zu erwachen, die Köpfe voller ferner Befehle in etwas, das an Gaudimm grenzt."],
   eintraege:[
    {t:"Die richtigen Fragen", typ:"Merkmal", x:"Besucher der Kilderkin, die dem Sog des Tanzes widerstehen können, beginnen vielleicht, Muster zu erkennen, wenn sie genau hinsehen. Es gibt Ordnung im Chaos, eine Art Hüten in der Art, wie sich die Luft bewegt und die Beats von Ort zu Ort anschwellen. Das Innere des Schiffs wirkt weniger wie eine Party und mehr wie ein Laborexperiment, und die aufragende Gestalt des Kommandoturms am Heck des Schiffs (nur vom Rülpsschlot an Höhe erreicht) wirkt allzu nah und allzu wachsam.", i:"Fragen zu stellen oder beiläufige Bemerkungen dazu zu machen, ist ein rascher Weg, vom Schiff geworfen zu werden oder, wenn die Fragen ungewöhnlich scharfsinnig sind, zu einer Privataudienz bei den Hohen Majestäten selbst hinaufgeleitet zu werden."},
    {t:"Mykomesmerische Agenten", typ:"Merkmal", x:"Warum fällt es den Tänzern so schwer, sich von dem Schiff zu lösen, das die Majestäten kontrollieren? Nicht allein, weil ein Ort solcher Freude sich so sehr vom Rest der Myconica unterscheidet oder weil die zügellose Hingabe, die er bietet, schwer zu verlassen ist, sondern weil Tänzer gedrängt werden zu bleiben, bis die richtige Art von Spore in ihrem Geist Wurzeln geschlagen hat – eine mit subversiven, revolutionären Neigungen.", i:"Diese Spore kann entfernt werden, wenn sie erkannt wird, bevor sie aus der Ferne aktiviert wird, auch wenn der Vorgang wahrscheinlich schwierig ist."},
    {t:"Ein Hinweis zum Ton", typ:"Hinweis", x:"Die Hohen Majestäten wie hier dargestellt einzubeziehen, kann den Ton der Kilderkin drastisch verändern, von einem Ort besorgniserregender, aber im Grunde recht vergnüglicher Ausschweifung zum verdrehten Samen einer dunklen und instabilen Zukunft. Verwendung auf eigene Gefahr!"}]}
 ],
 see:{ p:268,
  handel:[{t:"Dimms Fleisch",d:"export",x:"Auch wenn es etwas makaber ist: Pilzproben direkt aus den sich ausbreitenden Wellen der Myconica können in anderen Reichen als Forschungsmaterial äußerst wertvoll sein."},
          {t:"Sporenhund-Welpen",d:"export",x:"Auf den Flächen sind Sporenhunde häufig, doch jenseits der Reichsgrenzen lassen sie sich erstaunlich schwer verlässlich züchten. Das hält die Leute nicht vom Versuch ab."},
          {t:"Phosphorsporen",d:"export",x:"Eine verlässliche Lichtquelle in einer Welt, in der Flamme eine absurde Gefahr darstellt: Die natürliche Fülle leuchtender Sporen der Myconica wird in beeindruckenden Mengen abgefüllt und exportiert."},
          {t:"Saubere Luft",d:"import",x:"Tanks davon sind wertvoll, doch Filtermechanismen (wie sie bei den neumodischen Tauchbooten verwendet werden, über die alle zu reden scheinen) sind ein Vielfaches ihres Gewichts an seltenem Bergegut wert."},
          {t:"Parasiten-Stecklinge",d:"import",x:"Werden für die Haine des Foxfire Ocean gebraucht, um einen frischen und stetigen Strom neuer Früchte und Gemüse in den Höhlen unter dem pilzverstopften Geflecht zu sichern."},
          {t:"Essig",d:"import",x:"Einiges geht in die Küchen der Kilderkin Majestic, das meiste dient aber als Hilfsmittel für Schiffe, die versuchen, Dimm’s Embrace zu erkunden."}],
  wache:{
   frieden:["Ein Schwall goldener Sporen, in die Luft geschleudert.","Ein vorbeifahrendes Schiff, das eures mit einem üblichen Gruß und einem Handelsangebot anfunkt.","Ein Silberpuls am Taghimmel, als ein Zittern von unten Energie durch die Myzel-Aurora pumpt.","Sporenhunde, gezähmt von Generationen vorbeiziehender Wildsegler, die müßig in der aufgebrochenen Spur spielen, die ihr hinterlasst.","Ein Geisterschaft, sonst so bleich und abweisend, bekritzelt mit riesigen Botschaften der Hoffnung, die die Stimmung der Unterbesatzung heben.","Ein einsamer Entdecker auf einem Outrider, der unter dem Jubel aller an Deck vorbeirast."],
   ordnung:["Ein Blick auf die Kilderkin Majestic, die Licht, Gelächter und Musik in die Nacht ergießt.","Pfähle, hart in den Wuchs getrieben, die den Weg zu einem fernen Hafen markieren.","Ein für die Wellen der Myconica angepasstes Tauchboot, die Crew draußen auf dem gewölbten Rumpf mit Essigfässern.","Der Kadaver einer Verwerfungsspinne mit einer bizarren Reihe von Rohren und Drähten, die von ihren Mundwerkzeugen wegführen.","Himmelsfischer, die ihren Fang heimschleppen.","Das Wrack eines segelgetriebenen Schiffs, fast völlig von den Pilzwellen verzehrt."],
   natur:["Ein Rudel Rochen, das die Oberfläche durchbricht und sich ein paar Augenblicke sonnt, bevor es in seine übliche lichtlose Welt hinabtaucht.","Eine Zone niedrigen Wuchses, die mehrere astlose Eisenwurzeln freilegt, bleich im Sonnenlicht.","Ein Spalt in den Wellen, dessen enthüllte Tiefen grün glühen.","Ein Angriff auf das Schiff durch einen verwirrten Grabenden Rochen.","Eine Zunahme der ohnehin dichten Sporenwolken, die die Sicht noch weiter senkt.","Ein Wurzelbeben weit unten, das neue Verwerfungen durch den Körper von Dimm reißt und das Meer um euch in ein Netz aus Wunden verwandelt."]},
  passagiere:["Ein Duo Himmelsfischer auf der Suche nach einem neuen Platz für den Sommer.","Eine Gau, begierig, zu erkunden, was womöglich ihre Heimat ist, auch wenn sie wohl mit jeder Etappe der Reise desillusionierter wird.","Totholzbauern aus dem Foxfire Ocean, die ihr Luftschiff bei einem Rocheneinschlag verloren haben und einen anderen Weg brauchen, ihre Fracht zum Mond unter den Wellen zurückzubringen.","Ein alchemistischer Forscher auf persönlicher Mission, Antipilzmittel zu erforschen.","Ein Ironbound mit einer Silberseele, auf der Suche nach der Quelle eines seiner Bauteile.","Aurora-Schaulustige mit Schnappsographie-Kästen und einer riesigen Auswahl an Verschlüssen und Linsen, die einen Zeitraffer des strahlenden Nachthimmels über der Myconica aufnehmen wollen."],
  gefahren:[
   {t:"Die Luft selbst", x:"ist eine tödliche Mischung aus Sporen und Wärme, die perfekte Bedingung für Wachstum und Ausbreitung von Infektionen."},
   {t:"Grabende Rochen", id:"grabende-rochen", x:"auf der Suche nach sich ausbreitender Sapienz."},
   {t:"Anti-Sanktum-Plünderer", x:"Gau, aus The First verbannt wegen ihrer Überzeugungen über das Reich, in dem sie leben, und die wahre Natur von Dimm."},
   {t:"Verwilderte Sporenhunde", x:"die in Rudeln über die Pilzflächen rasen, um alles nichtmyconische Leben, das sie finden, anzugreifen und zu verzehren."},
   {t:"Jagende Fraßwolken", x:"riesige Ansammlungen partikulären Lebens, vom Licht der Aurora geweckt."},
   {t:"Die Gebrochene Hand", x:"auch Linke Hand der Tiefen genannt, ein apokrypher Protoleviathan, über dessen Gestalt sich niemand einig werden kann."}]},
 extra:{t:"Die Gefahr des Atmens", p:269,
  intro:"In den sporenverstopften Lüften der Myconica tragen sich Hunderte einzigartiger Krankheiten und Infektionen. Während Einheimische sich so angepasst haben, dass sie den meisten (wenn nicht allen) widerstehen, könnten Besucher, die nicht darauf achten, wann und wie sie atmen, sich plötzlich mit einer dieser Krankheiten wiederfinden:",
  eintraege:[
   {t:"Skelettquirl", x:"Eine Verdrehung innerer Strukturen, die nur jene befällt, die ein Endoskelett besitzen. Bei einem Ardent äußert sie sich langsam und entwickelt sich über Wochen zunehmender Schmerzen und Steifheit in den Gelenken. Ketra trifft es weit schlimmer, selbst wenn ihre Skelette nicht aus Knochen bestehen – etwas an ihrer Biologie versetzt den Skelettquirl in Überdrehzahl, sodass man ihre inneren Strukturen durch ihre durchscheinende Haut tatsächlich sich umformen und drehen sehen kann."},
   {t:"Aurora-Fesseln", x:"Eine besonders heimtückische Infektion, die schwer zu erkennen ist, bis sie ihr Endstadium erreicht, es sei denn, der Betroffene verbringt viel Zeit nachts im Freien. Was als Drang beginnt, unter freiem Himmel zu bleiben und sich von anderen abzusondern, wird zur Manie, deren wahre Ursache (und deren Ausgang) sich ohne übermäßiges Trauma kaum umkehren lässt. Der Nachthimmel enthüllt die Wahrheit: dass der Betroffene durch einen dünnen Strang mit der Aurora darüber verbunden ist. Der Versuch, diesen Strang zu zerreißen, versetzt ihn in Raserei, die Augen und der Mund brennen von krankhaft grünem Licht, und die Muskeln wogen vor himmelsgeborgter Stärke."},
   {t:"Flussbiegung", x:"Eine einfache, aber gefährliche Infektion; Flussbiegung bildet im Wirt neue Organe aus, die einen steten Strom sporenanziehender Pheromone abgeben. Betroffene sind womöglich äußerst verwirrt, warum Sporenwolken ihnen folgen, selbst über die Grenzen der Myconica hinaus."},
   {t:"Crezzerdimm", x:"Zum Glück äußerst selten verläuft eine Crezzerdimm-Infestation langsam, aber dramatisch. Ein Infizierter verwandelt sich über Jahre in eine sich bewegende Pilzmasse, im selben Orangeviolett wie Dimm selbst. Manche, die mit Crezzerdimm leben, werden für Gau gehalten, aber nie von einem echten Gau."}]}
};
